package localchat;
import java.nio.file.*;import java.util.*;import javax.swing.*;
/** Synthetic factory roots only. No actual network/project modifications or live model calls. */
public final class ProjectLocationsTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static Object config(Path a,Path b){return Json.obj("projectRoots",List.of(Json.obj("factory","soest","path",a.toString()),Json.obj("factory","veenoord","path",b.toString())));}
 static void configure(LocalChat app,Object value)throws Exception{var field=LocalChat.class.getDeclaredField("toolsConfig");field.setAccessible(true);field.set(app,value);}
 static void choose(LocalChat app,String needle)throws Exception{ComposerAssist assist=FeatureTest.field(app,"composerAssist");var button=ComposerAssistTest.all(assist).stream().filter(c->c instanceof JRadioButton radio&&Objects.toString(radio.getClientProperty("interaction.option"),"").toLowerCase(Locale.ROOT).contains(needle.toLowerCase(Locale.ROOT))).map(c->(JRadioButton)c).findFirst().orElseThrow();button.doClick();assist.send.doClick();}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");Path a=Files.createDirectories(home.resolve("factory-a")),b=Files.createDirectories(home.resolve("factory-b"));Path pa=Files.createDirectory(a.resolve("507045_Project-A")),pb=Files.createDirectory(b.resolve("507045_Project-B"));Files.createDirectory(a.resolve("5070450_wrong-number"));Files.createDirectory(a.resolve("507046_Only-A"));
  var roots=ProjectLocations.roots(config(a,b));var result=ProjectLocations.scan("507045",roots,3000);check(result.matches().size()==2&&result.unavailable().isEmpty(),"two factories found; numeric prefix excludes different project");check(ProjectLocations.parse(result.json()).matches().size()==2,"pending discovery is serializable without credentials");check(ProjectLocations.answer(result,"soest").folder().equals(pa.toRealPath().toString()),"free factory name resolves only unique candidate");check(ProjectLocations.explicit(result,"Continua proiectul 507045 la veenoord").root().factory().equals("veenoord"),"current explicit factory can override previous chat choice");check(ProjectLocations.project("Am pus un proiect nou: 507045",a,"").equals("507045"),"project extracted from current user request");check(ProjectLocations.project("cat este 123456?",a,"").isEmpty(),"ordinary number does not trigger project network scan");
  var missing=ProjectLocations.scan("507045",List.of(roots.get(0),new ProjectLocations.Root("other",home.resolve("offline").toString())),3000);check(missing.matches().size()==1&&missing.unavailable().size()==1,"unreachable root stays unverified rather than proving uniqueness");
  var unknown=ProjectLocations.scan("507045",List.of(new ProjectLocations.Root("",a.toString())),3000);check(ProjectLocations.needsName(unknown)&&ProjectLocations.question(unknown).questions().get(0).id().equals("factory-name"),"drive path alone never assigns factory");
  var aliases=ProjectLocations.scan("507045",List.of(roots.get(0),new ProjectLocations.Root("soest",a.resolve(".").toString())),3000);check(aliases.matches().size()==1,"same physical folder/factory aliases do not invent duplicates");var conflict=ProjectLocations.scan("507045",List.of(roots.get(0),new ProjectLocations.Root("alphen",a.resolve(".").toString())),3000);check(conflict.matches().size()==2,"conflicting factory identities on same physical folder remain ambiguous");check(!ProjectLocations.describe(Json.obj("projectRoots",List.of(Json.obj("factory","soest","path",a.toString(),"apiKey","PRIVATE-EXTRA-FIELD")))).contains("PRIVATE-EXTRA-FIELD"),"only validated root metadata reaches model context");
  LocalChat[] app={null};try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("Done B",40,5)),FeatureTest.json(FeatureTest.answer("Continued B",40,5)),FeatureTest.json(FeatureTest.answer("Done A",40,5)),FeatureTest.json(FeatureTest.answer("General answer",20,5)))){
   FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("app"),server.url());configure(app[0],config(a,b));});NormalModeTest.ask(app[0],"Continua proiectul 507045. Verifica emailul nou.");Path[] saved={null};
   FeatureTest.edt(()->{var assist=FeatureTest.<ComposerAssist>field(app[0],"composerAssist");check(assist.waiting()&&server.requests.isEmpty()&&NormalModeTest.history(app[0]).isEmpty(),"ambiguous project pauses before model, memory and tools");check(AttachmentTest.input(app[0]).getText().contains("emailul nou"),"factory prompt preserves original draft");FeatureTest.call(app[0],"saveConversation",new Class<?>[]{});saved[0]=FeatureTest.field(app[0],"conversationFile");var loaded=Conversations.load(saved[0]);check(!loaded.state().factoryPending.isBlank(),"pending factory choices persist per chat");FeatureTest.call(app[0],"newChat",new Class<?>[]{});FeatureTest.call(app[0],"openSession",new Class<?>[]{Conversations.Saved.class},loaded);check(FeatureTest.<ComposerAssist>field(app[0],"composerAssist").waiting()&&server.requests.isEmpty(),"restoring question performs zero inference");choose(app[0],"veenoord");});FeatureTest.idle(app[0]);
   FeatureTest.edt(()->{check(server.requests.size()==1&&AttachmentTest.state(app[0]).factoryRoot.equals(b.toString()),"explicit factory choice unlocks exactly one model request");String wire=Json.write(server.requests.get(0));check(wire.contains("Confirmed processing scope for project 507045")&&wire.contains("veenoord"),"actual model payload includes confirmed factory scope");check(NormalModeTest.history(app[0]).stream().filter(m->m.role.equals("user")).findFirst().orElseThrow().content.equals("Continua proiectul 507045. Verifica emailul nou."),"factory UI does not rewrite original user question");});
   NormalModeTest.ask(app[0],"Continua proiectul 507045.");FeatureTest.edt(()->check(server.requests.size()==2&&!FeatureTest.<ComposerAssist>field(app[0],"composerAssist").waiting(),"confirmed same-project factory is rechecked and reused"));
   NormalModeTest.ask(app[0],"Continua proiectul 507045 la soest.");FeatureTest.edt(()->{check(server.requests.size()==3&&AttachmentTest.state(app[0]).factoryName.equals("soest"),"explicit current request replaces older factory scope");FeatureTest.call(app[0],"newChat",new Class<?>[]{});AttachmentTest.input(app[0]).setText("Continua proiectul 507045");FeatureTest.call(app[0],"send",new Class<?>[]{});FeatureTest.call(app[0],"stop",new Class<?>[]{});});Thread.sleep(250);FeatureTest.edt(()->{check(server.requests.size()==3&&!FeatureTest.<Boolean>field(app[0],"busy")&&AttachmentTest.input(app[0]).getText().contains("507045"),"Stop during preflight keeps draft without model request");NormalModeTest.mode(app[0],false);});NormalModeTest.ask(app[0],"Ce este lumina?");FeatureTest.edt(()->{check(server.requests.size()==4&&!Json.write(server.requests.get(3)).contains("Private configured project roots"),"Normal neither scans nor injects factory configuration");app[0].dispose();});
  }finally{FeatureTest.edt(()->{for(var w:java.awt.Window.getWindows())w.dispose();});}
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("Confirmed Alphen",25,5)))){
   FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("unknown-app"),server.url());configure(app[0],Json.obj("projectRoots",List.of(Json.obj("factory","","path",a.toString()))));});NormalModeTest.ask(app[0],"Continua proiectul 507045.");FeatureTest.edt(()->{check(server.requests.isEmpty()&&FeatureTest.<ComposerAssist>field(app[0],"composerAssist").waiting(),"unknown root asks actual factory before model");choose(app[0],"Alphen");});FeatureTest.idle(app[0]);FeatureTest.edt(()->{check(server.requests.size()==1&&AttachmentTest.state(app[0]).factoryName.equals("alphen"),"user-confirmed factory for mixed historical root survives recheck");app[0].dispose();});
  }
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("must not be sent",10,1)))){
   FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("mismatch-app"),server.url());configure(app[0],config(a,b));});NormalModeTest.ask(app[0],"Continua proiectul 507046 la alphen.");FeatureTest.edt(()->{check(server.requests.isEmpty()&&FeatureTest.<ComposerAssist>field(app[0],"composerAssist").waiting(),"single Soest match cannot override requested Alphen");FeatureTest.call(app[0],"newChat",new Class<?>[]{});AttachmentTest.input(app[0]).setText("Continua proiectul 507045");FeatureTest.call(app[0],"send",new Class<?>[]{});AttachmentTest.input(app[0]).setText("my draft changed during lookup");});FeatureTest.idle(app[0]);FeatureTest.edt(()->{check(server.requests.isEmpty()&&AttachmentTest.input(app[0]).getText().equals("my draft changed during lookup"),"draft edit cancels automatic continuation after lookup");app[0].dispose();});
  }
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("must not be sent",10,1)))){
   FeatureTest.edt(()->{app[0]=AttachmentTest.window(home.resolve("loading-app"),server.url());configure(app[0],config(a,b));AttachmentTest.input(app[0]).setText("Continua proiectul 507045");System.setProperty("localchat.test","false");try{FeatureTest.call(app[0],"send",new Class<?>[]{});}finally{System.setProperty("localchat.test","true");}check(server.requests.isEmpty()&&!FeatureTest.<Boolean>field(app[0],"busy"),"startup cannot bypass root configuration loading");var error=LocalChat.class.getDeclaredField("toolsConfigError");error.setAccessible(true);error.set(app[0],"invalid fixture configuration");FeatureTest.call(app[0],"send",new Class<?>[]{});check(server.requests.isEmpty()&&AttachmentTest.input(app[0]).getText().contains("507045"),"invalid configuration blocks MBS without losing draft");app[0].dispose();});
  }
  for(String language:I18n.CODES){I18n.setLanguage(language);check(ProjectLocations.question(result).message().contains("507045"),"localized factory question "+language);}
  System.out.println("PASS: "+checks+" factory preflight checks; duplicate IDs, root errors, no guessing, explicit choices, persistence, Stop and Normal isolation");System.exit(0);
 }
}
